-- Tin đăng dùng chung cho Vercel. Áp dụng sau 0001_profiles.sql.
-- Không tạo tài khoản/mật khẩu mẫu, không tự gán tin theo số điện thoại.
begin;
create table if not exists public.rental_listings (
  id text primary key,
  landlord_id uuid unique references public.profiles(id) on delete cascade,
  data jsonb not null check (jsonb_typeof(data) = 'object'),
  status text not null default 'pending' check (status in ('pending','approved','rejected')),
  visible boolean not null default true,
  reason text not null default '',
  version integer not null default 1 check (version > 0),
  decided_by uuid references public.profiles(id),
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);
create index if not exists rental_listings_public on public.rental_listings (status,visible,created_at);
alter table public.rental_listings enable row level security;
-- Client chỉ được đọc. Tạo/sửa/duyệt bắt buộc qua API xác thực token ở máy chủ.
revoke all on public.rental_listings from anon, authenticated;
grant select on public.rental_listings to anon, authenticated;
grant all on public.rental_listings to service_role;
drop policy if exists rental_listings_public_read on public.rental_listings;
create policy rental_listings_public_read on public.rental_listings for select to anon, authenticated
  using (status = 'approved' and visible = true);
drop policy if exists rental_listings_owner_read on public.rental_listings;
create policy rental_listings_owner_read on public.rental_listings for select to authenticated
  using (landlord_id = (select auth.uid()));
drop policy if exists rental_listings_admin_read on public.rental_listings;
create policy rental_listings_admin_read on public.rental_listings for select to authenticated
  using (exists (select 1 from public.profiles where id = (select auth.uid()) and role = 'admin'));

